const config = {
    "previewFeatures": [],
    "clientVersion": "7.9.1",
    "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
    "activeProvider": "postgresql",
    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider     = \"prisma-client\"\n  output       = \"../generated/prisma\"\n  moduleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nmodel User {\n  id          String   @id @default(uuid())\n  email       String   @unique\n  // Null until an account created by an identity provider picks one. Postgres\n  // allows several NULLs under a unique constraint, so pending accounts can\n  // coexist.\n  username    String?  @unique\n  // Null for accounts that only sign in through an identity provider.\n  password    String?\n  // Google's stable subject claim. Stored rather than matching on email, so a\n  // user who later changes their Google address still resolves to this account.\n  googleId    String?  @unique\n  // The same claim from the club's Keycloak realm, kept in its own column\n  // rather than sharing one with `googleId`: a single column would need a\n  // second one naming the issuer, and every lookup would have to match both or\n  // risk resolving an account by another provider's subject. Unique for the\n  // reason `googleId` is — two rows carrying one subject would mean whichever\n  // the query returned first captured every sign-in for both. The index is\n  // what holds under concurrency; the check preceding the write only buys a\n  // clean message.\n  keycloakId  String?  @unique\n  displayName String\n  bio         String?\n  avatarUrl   String?\n  coverUrl    String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  mixes       Mix[]\n  favorites   Favorite[]\n  playHistory PlayHistory[]\n  playlists   Playlist[]\n  comments    Comment[]\n\n  // Rows where this user is the one doing the following.\n  following  Follow[] @relation(\"Following\")\n  // Rows where this user is being followed (their followers).\n  followedBy Follow[] @relation(\"Followers\")\n\n  passwordResetTokens PasswordResetToken[]\n\n  @@map(\"users\")\n}\n\n/// A bearer credential: whoever holds the clear token can take the account, so\n/// it is treated like a password. Only the SHA-256 hash is stored — the\n/// database is one more copy of every live token, and a readable one is a\n/// working key. SHA-256 rather than bcrypt is deliberate: the input is already\n/// 256 bits from `crypto.randomBytes`, so there is nothing to brute-force, and\n/// the lookup has to stay a single indexed read.\nmodel PasswordResetToken {\n  id        String    @id @default(uuid())\n  tokenHash String    @unique\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n  @@map(\"password_reset_tokens\")\n}\n\nmodel Mix {\n  id            String   @id @default(uuid())\n  title         String\n  /// Le titre rendu passable dans une URL : `/mixes/<compte>/<slug>`. Figé à la\n  /// création et jamais recalculé — un titre corrigé ne doit pas casser les liens\n  /// déjà partagés. Unique par compte seulement : deux personnes ont le droit de\n  /// publier « mix 57 ». Voir `src/common/slug.ts`.\n  slug          String\n  description   String?\n  /// Le nom de l'artiste tel que la source l'écrit, casse comprise. Null sur\n  /// les mix déposés à la main, où l'artiste est le compte lui-même — et sur\n  /// tous les mix antérieurs à cette colonne, qui ne sont pas rétro-remplis :\n  /// leur artiste vit dans les tags, en minuscules et sans marqueur.\n  artist        String?\n  // Exactly one audio source: either `audioUrl` alone, or `sourceType` and\n  // `sourceRef` together. Prisma cannot express that, so `MixesService`\n  // enforces it on create and update.\n  /// R2 object key. Null when the audio lives elsewhere.\n  audioUrl      String?\n  /// 'mixcloud' | 'remote'. Null when the audio is on R2. A plain string, not\n  /// an enum: adding a source must not need a migration.\n  sourceType    String?\n  /// Interpreted according to `sourceType`: a cloudcast key\n  /// (\"/Notamusic/antimythes/\") or a directly playable audio URL.\n  sourceRef     String?\n  /// La page où la source publie ce mix — l'émission chez Ouïedire, l'épisode\n  /// chez LYL. Distincte de `sourceRef`, qui ne désigne que le fichier ou la\n  /// clé à lire : d'un mp3 nu on ne remonte pas toujours à sa page. C'est elle\n  /// que l'encart infos donne en lien. Null sur un mix déposé à la main, qui\n  /// n'a pas de source, et sur ceux importés avant cette colonne que\n  /// `backfill-source-page-urls` n'a pas su retrouver.\n  sourcePageUrl String?\n  coverUrl      String?\n  durationSec   Int?\n  playsCount    Int      @default(0)\n  tags          String[] @default([])\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  tracklist     TracklistEntry[]\n  favorites     Favorite[]\n  playHistory   PlayHistory[]\n  playlistItems PlaylistItem[]\n  comments      Comment[]\n\n  @@unique([userId, slug])\n  @@index([userId])\n  @@index([createdAt])\n  @@map(\"mixes\")\n}\n\nmodel Playlist {\n  id          String   @id @default(uuid())\n  title       String\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  items PlaylistItem[]\n\n  @@index([userId])\n  @@index([createdAt])\n  @@map(\"playlists\")\n}\n\nmodel PlaylistItem {\n  id       String   @id @default(uuid())\n  // Insertion order. Gaps are expected after removals; reads always sort by this.\n  position Int\n  addedAt  DateTime @default(now())\n\n  playlistId String\n  playlist   Playlist @relation(fields: [playlistId], references: [id], onDelete: Cascade)\n\n  mixId String\n  mix   Mix    @relation(fields: [mixId], references: [id], onDelete: Cascade)\n\n  @@unique([playlistId, mixId])\n  @@index([playlistId, position])\n  @@map(\"playlist_items\")\n}\n\nmodel Favorite {\n  id        String   @id @default(uuid())\n  createdAt DateTime @default(now())\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  mixId String\n  mix   Mix    @relation(fields: [mixId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, mixId])\n  @@index([mixId])\n  @@map(\"favorites\")\n}\n\nmodel Follow {\n  id        String   @id @default(uuid())\n  createdAt DateTime @default(now())\n\n  followerId String\n  follower   User   @relation(\"Following\", fields: [followerId], references: [id], onDelete: Cascade)\n\n  followingId String\n  following   User   @relation(\"Followers\", fields: [followingId], references: [id], onDelete: Cascade)\n\n  @@unique([followerId, followingId])\n  @@index([followingId])\n  @@index([followerId])\n  @@map(\"follows\")\n}\n\nmodel PlayHistory {\n  id       String   @id @default(uuid())\n  playedAt DateTime @default(now())\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  mixId String\n  mix   Mix    @relation(fields: [mixId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, mixId])\n  @@index([userId])\n  // Les suggestions partent de \"qui d'autre a écouté ce mix\", donc d'un filtre\n  // sur mixId seul. L'unique ci-dessus a userId en tête de clé et ne peut pas\n  // le servir : sans cet index, chaque page de mix scanne toute la table.\n  @@index([mixId])\n  @@map(\"play_history\")\n}\n\nmodel Comment {\n  id          String   @id @default(uuid())\n  body        String\n  timecodeSec Int?\n  createdAt   DateTime @default(now())\n\n  mixId String\n  mix   Mix    @relation(fields: [mixId], references: [id], onDelete: Cascade)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  parentId String?\n  parent   Comment?  @relation(\"Replies\", fields: [parentId], references: [id], onDelete: Cascade)\n  replies  Comment[] @relation(\"Replies\")\n\n  @@index([mixId])\n  @@index([parentId])\n  @@map(\"comments\")\n}\n\nmodel TracklistEntry {\n  id          String @id @default(uuid())\n  artist      String\n  title       String\n  timecodeSec Int\n\n  mixId String\n  mix   Mix    @relation(fields: [mixId], references: [id], onDelete: Cascade)\n\n  @@index([mixId])\n  @@map(\"tracklist_entries\")\n}\n",
    "runtimeDataModel": {
        "models": {},
        "enums": {},
        "types": {}
    },
    "parameterizationSchema": {
        "strings": [],
        "graph": ""
    }
};
